const $=s=>document.querySelector(s),escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const e=escapeHTML;
const tg=window.Telegram?.WebApp;tg?.ready();tg?.expand();setupMobile();let state,page='home',tab='groups',requestTab='pending',day=new Date(Date.now()+5*3600000).toISOString().slice(0,10),venueList=[],reportFrom=day.slice(0,7)+'-01',reportTo=day;const money=n=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'KZT'}).format(n/100);
async function api(path,data){const r=await fetch(path,{method:data?'POST':'GET',headers:{'Content-Type':'application/json','X-Telegram-Init-Data':tg?.initData||''},body:data?JSON.stringify(data):undefined});const result=await r.json();if(!r.ok)throw Error(result.error||'Не удалось выполнить запрос');return result}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
function modal(html){$('#dialog').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
function closeDialog(){$('#dialog').close()}
async function mutate(action,data){try{state=await api('/api/action',{action,...data});closeDialog();render();toast('Сохранено')}catch(error){toast(error.message)}}
function formDialog(title,fields,action,extra={}){modal(`<h2>${e(title)}</h2><form class="fields">${fields}<div class="actions"><button class="primary">Сохранить</button><button type="button" onclick="closeDialog()">Отмена</button></div></form>`);$('#dialog form').onsubmit=async event=>{event.preventDefault();const form=event.target,button=form.querySelector('button');button.disabled=true;const data=Object.fromEntries(new FormData(form));if(action==='group')data.days=new FormData(form).getAll('days').map(Number);if(action==='payment')data.hours=Number(data.hours);await mutate(action,{...extra,...data});button.disabled=false}}
function heading(t,a=''){return `<div class="heading"><h1>${e(t)}</h1>${a}</div>`}
function field(label,name,value='',type='text'){return `<label>${e(label)}<input name="${name}" type="${type}" value="${e(value)}" required></label>`}
function navigate(p){page=p;render()}
function render(){const coach=state.user.role==='coach';$('#greeting').textContent='Приветствую, '+state.user.fullName+' 👋';$('#nav').innerHTML=(coach?[['home','Главное'],['requests','Заявки'],['groups','Группы'],['profile','Профиль']]:[['home','Главное'],['trainers','Тренеры'],['profile','Профиль']]).map(([p,t])=>`<button class="${page===p?'active':''}" onclick="navigate('${p}')">${t}</button>`).join('');$('#screen').innerHTML=page==='home'?home():page==='requests'?requestsView():page==='groups'?groupsView():page==='trainers'?trainersView():page==='reports'?reportsView():page==='premium'?premiumView():profileView()}
function status(s){return s.status==='completed'?'Завершена':s.status==='cancelled'?'Отменена':Date.now()/1000>=s.begins?'Тренировка идёт':'Запланирована'}
function home(){const coach=state.user.role==='coach',uid=state.user.telegramId;let list=state.sessions.filter(s=>s.date===day).sort((a,b)=>(a.status==='completed')-(b.status==='completed')||a.begins-b.begins);const mine=state.students[0];return (coach?'':heading('Мои тренировки'))+(!coach?`<div class="card hero-balance">На балансе<strong>${mine?.hours||0} ч</strong></div>`:'')+`<div class="section-title"><h2>Расписание</h2><input aria-label="Дата календаря" class="calendar-date" type="date" value="${day}" onchange="day=this.value;render()"></div>${weekCalendar()}<div class="section-title"><h2>${new Date(day+'T12:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}</h2><span class="meta">${list.length} занятий</span></div>${list.map(s=>{const now=Date.now()/1000,live=s.status==='scheduled'&&now>=s.begins,soon=s.status==='scheduled'&&s.begins>now&&s.begins-now<=3600;const zero=state.students.filter(p=>s.members.includes(p.telegramId)&&p.hours===0&&!s.absent.includes(p.telegramId));return `<div class="card session ${live?'live':s.status==='completed'?'completed':soon?'soon':''}"><div class="time">${s.time}<small>1 час</small></div><div class="body"><span class="badge">${soon?'Скоро · '+Math.ceil((s.begins-now)/60)+' мин':status(s)}</span><h3>${e(s.name)}</h3><div class="meta">${e(s.place)}</div>${s.reason?`<p>${e(s.reason)}. Часы не снимутся.</p>`:''}${coach&&s.status==='scheduled'&&s.begins-now<=86400&&zero.length?`<div class="balance-warning">Нет часов: ${zero.map(p=>e(p.displayName||p.fullName)).join(', ')}<button onclick="page='groups';tab='students';render()">К ученикам</button></div>`:''}<div class="actions">${coach?`<button onclick="openSession('${s.id}')">Открыть тренировку</button>`:s.status==='scheduled'?`<button ${s.begins-now<86400||s.absent.includes(uid)?'disabled':''} onclick="mutate('absence',{id:'${s.id}'})">${s.absent.includes(uid)?'Участие отменено':'Не приду'}</button>`:''}</div></div></div>`}).join('')||'<p class="empty">На эту дату тренировок нет.</p>'}`}
function requestsView(){return heading('Заявки','<button onclick="exportGate()">↓ Выгрузить отчёт</button>')+`<div class="tabs">${[['pending','Входящие'],['accepted','Принятые'],['rejected','Отклонённые']].map(([id,t])=>`<button class="${requestTab===id?'active':''}" onclick="requestTab='${id}';render()">${t} · ${state.requests.filter(r=>r.status===id).length}</button>`).join('')}</div><div class="card">${state.requests.filter(r=>r.status===requestTab).map(r=>`<div class="person"><div class="info"><strong>${e(r.playerName)}</strong><div class="student-comment">${e(r.comment)}</div></div>${r.status==='pending'?`<button class="primary" onclick="mutate('decision',{id:'${r.id}',status:'accepted'})">Принять</button><button onclick="mutate('decision',{id:'${r.id}',status:'rejected'})">Отклонить</button>`:r.status==='accepted'?`<button onclick="chat(${r.player})">Telegram-чат</button>`:''}</div>`).join('')||'<p>Заявок пока нет.</p>'}</div>`}
function filterList(value){document.querySelectorAll('[data-search]').forEach(el=>el.hidden=!el.dataset.search.toLowerCase().includes(value.toLowerCase()))}
function groupsView(){return heading('Группы и ученики',tab==='groups'?'<button class="primary" onclick="newGroup()">+ Создать</button>':'')+`<div class="tabs"><button onclick="tab='groups';render()" class="${tab==='groups'?'active':''}">Группы · ${state.groups.length}</button><button onclick="tab='students';render()" class="${tab==='students'?'active':''}">Ученики · ${state.students.length}</button></div><label class="list-search">Поиск<input type="search" oninput="filterList(this.value)" placeholder="Имя или название"></label><div class="cards">${tab==='groups'?state.groups.map(g=>`<article class="card live-group-card compact-group" data-search="${e(g.name)}" onclick="if(!event.target.closest('button'))groupDetail('${g.id}')" onkeydown="if(event.target===this&&(event.key==='Enter'||event.key===' ')){event.preventDefault();groupDetail('${g.id}')}" tabindex="0" aria-label="Открыть группу ${e(g.name)}"><div class="row"><span class="badge">${e(g.type)}</span><button aria-label="Действия с группой" onclick="event.stopPropagation();groupMenu('${g.id}')">⋯</button></div><h2>${e(g.name)}</h2><div class="meta">🗓 ${groupDays(g)} · ${g.time}</div><div class="compact-footer"><span>👥 ${g.members.length} уч.</span><span aria-hidden="true">Подробнее →</span></div></article>`).join('')||'<p>Создайте первую группу. Учеников можно добавить позже.</p>':[...state.students].sort((a,b)=>(b.hours===0)-(a.hours===0)).map(p=>{const g=state.groups.find(g=>g.members.includes(p.telegramId));return `<div class="card student-card ${p.hours===0?'zero-hours':''}" data-search="${e((p.displayName||p.fullName)+' '+p.comment)}"><div class="row"><h3>${e(p.displayName||p.fullName)}</h3><strong class="hours-pill">${p.hours} ч</strong></div><span class="badge">${e(g?.name||'Без группы')}</span><p>${e(p.comment)}</p>${!p.hours?'<p class="renewal-note">Часы закончились. Уточните продолжение занятий и примите оплату.</p>':''}<div class="actions"><button class="primary" onclick="payment(${p.telegramId})">+ Часы и оплата</button>${!g?`<button onclick="assignMenu(${p.telegramId})">Добавить в группу</button>`:''}<button onclick="renameStudent(${p.telegramId})">Изменить имя</button><button onclick="comment(${p.telegramId})">Комментарий</button><button onclick="chat(${p.telegramId})">Telegram</button></div></div>`}).join('')||'<p>Примите заявку игрока — он появится здесь.</p>'}</div>`}
function groupMenu(id){const g=state.groups.find(g=>g.id===id);modal(`<h2>${e(g.name)}</h2><div class="fields"><button onclick="rename('${id}')">Переименовать</button><button class="danger-text" onclick="deleteGroup('${id}')">Удалить</button><button onclick="closeDialog()">Закрыть</button></div>`)}
function rename(id){formDialog('Переименовать',field('Название','name',state.groups.find(g=>g.id===id).name),'rename',{id})}
function deleteGroup(id){modal(`<h2>Точно удалить группу?</h2><p>Группа исчезнет из списка, а её будущие тренировки будут отменены. Восстановить группу кнопкой будет нельзя.</p><p>Ученики, остатки часов, оплаты и завершённые занятия сохранятся.</p><div class="actions"><button class="danger-button" onclick="mutate('delete',{id:'${id}'})">Удалить</button><button onclick="closeDialog()">Отмена</button></div>`)}
function groupDays(g){return g.days.map(d=>['Вс','Пн','Вт','Ср','Чт','Пт','Сб'][d]).join(' · ')}
function groupDetail(id){const g=state.groups.find(g=>g.id===id),next=state.sessions.filter(s=>s.group===id&&s.status==='scheduled'&&s.ends>Date.now()/1000).sort((a,b)=>a.begins-b.begins)[0];modal(`<span class="badge">🎾 ${e(g.type)}</span><h2>${e(g.name)}</h2><div class="group-facts"><div>📍 <strong>Место</strong><p>${e(g.place)}</p></div><div>🗓 <strong>Расписание</strong><p>${groupDays(g)} · ${g.time} · 1 час</p></div><div>📅 <strong>Период</strong><p>${e(g.start)} — ${g.end?e(g.end):'без даты окончания'}</p></div>${next?`<div>⏱ <strong>Ближайшее занятие</strong><p>${next.date} в ${next.time}</p></div>`:''}</div><h3>👥 Ученики · ${g.members.length}</h3>${g.members.map(pid=>{const p=state.students.find(p=>p.telegramId===pid);return `<div class="person"><div class="info"><strong>${e(p?.displayName||p?.fullName)}</strong><div class="student-comment">${e(p?.comment||'')}</div></div><span class="hours-pill">${p?.hours||0} ч</span></div>`}).join('')||'<p>Учеников пока нет. Добавьте из принятых заявок.</p>'}<div class="actions"><button class="primary" onclick="addMember('${id}')">+ Добавить ученика</button><button onclick="closeDialog()">Закрыть</button></div>`)}
function addMember(id){const free=state.students.filter(p=>!state.groups.some(g=>g.members.includes(p.telegramId)));modal(`<h2>Добавить ученика</h2>${free.map(p=>`<button class="pick" onclick="mutate('assign',{id:'${id}',player:${p.telegramId}})">${e(p.displayName||p.fullName)}<small>${e(p.comment)}</small></button>`).join('')||'<p>Нет одобренных учеников без группы.</p>'}<button onclick="closeDialog()">Закрыть</button>`)}
function assignMenu(pid){modal(`<h2>Выберите группу</h2>${state.groups.filter(g=>g.type==='Групповая'||!g.members.length).map(g=>`<button class="pick" onclick="mutate('assign',{id:'${g.id}',player:${pid}})">${e(g.name)} · ${g.time}</button>`).join('')||'<p>Сначала создайте группу.</p>'}<button onclick="closeDialog()">Закрыть</button>`)}
async function newGroup(){try{venueList=await api('/api/venues?cityId='+state.user.cityId);formDialog('Новая группа',field('Название','name')+`<label>Тип<select name="type"><option>Групповая</option><option>Индивидуальная</option></select></label><label>Клуб / корт<select onchange="this.form.elements.place.value=this.value"><option value="">Указать вручную</option>${venueList.map(v=>`<option value="${e(v.name+' · '+v.address)}">${e(v.name+' · '+v.address)}</option>`).join('')}</select></label>`+field('Место и адрес','place',state.user.venue?[state.user.venue,state.user.address].filter(Boolean).join(' · '):'')+field('Время','time','19:00','time')+`<div class="days">${[1,2,3,4,5,6,0].map(d=>`<label><input type="checkbox" name="days" value="${d}">${['Вс','Пн','Вт','Ср','Чт','Пт','Сб'][d]}</label>`).join('')}</div>`+field('Начало','start',day,'date')+'<label>Окончание · необязательно<input type="date" name="end"></label><p>Учеников можно добавить после создания.</p>','group')}catch(err){toast(err.message)}}
function payment(pid){const p=state.students.find(p=>p.telegramId===pid);formDialog('Часы и оплата · '+p.fullName,field('Часы','hours','','number')+field('Оплачено, ₸','amount','','number')+field('Дата оплаты','date',day,'date')+field('Кто оплатил','payer',p.fullName)+'<label>Комментарий<textarea name="comment" maxlength="500"></textarea></label>','payment',{player:pid,nonce:crypto.randomUUID()});$('#dialog [name=hours]').min=1;$('#dialog [name=amount]').min=0;$('#dialog [name=amount]').step='.01'}
function comment(pid){formDialog('Комментарий тренера',`<label>Группа, дни и время<textarea name="comment" maxlength="500">${e(state.students.find(p=>p.telegramId===pid).comment)}</textarea></label>`,'comment',{player:pid})}
function chat(pid){const p=[...state.students,...state.trainers].find(p=>p.telegramId===pid);if(p?.username)(tg?.openTelegramLink?tg.openTelegramLink('https://t.me/'+p.username):window.open('https://t.me/'+p.username,'_blank','noopener'));else window.location.href='tg://user?id='+pid}
function openSession(id){const s=state.sessions.find(s=>s.id===id);modal(`<h2>${e(s.name)}</h2><span class="badge">${status(s)}</span>${s.members.map(pid=>`<div class="person"><div class="info"><strong>${e((state.students.find(p=>p.telegramId===pid)||{}).displayName||(state.students.find(p=>p.telegramId===pid)||{}).fullName)}</strong><label class="check attendance"><input type="checkbox" role="switch" ${s.absent.includes(pid)?'':'checked'} ${s.status!=='scheduled'?'disabled':''} onchange="updateAttendance('${s.id}',${pid},this)"><span class="switch-track"></span><span class="presence-label">${s.absent.includes(pid)?'Отсутствует':'Присутствует'}</span></label></div></div>`).join('')}<div class="actions">${s.status==='scheduled'?`<button ${s.begins-Date.now()/1000<=86400?'disabled':''} onclick="cancel('${id}')">Отменить тренировку</button>`:''}<button class="primary" onclick="closeDialog()">Закрыть</button></div>`)}
function cancel(id){formDialog('Отмена тренировки','<label>Причина<textarea name="reason" required maxlength="500"></textarea></label><p>Все участники получат причину отмены. Часы не снимутся.</p>','cancel',{id})}
function trainersView(){return heading('Тренеры · '+state.user.city)+`<label class="list-search">Поиск<input type="search" oninput="filterList(this.value)"></label><div class="cards">${state.trainers.map(t=>{const r=state.requests.find(r=>r.coach===t.telegramId&&r.status!=='rejected');return `<div class="card" data-search="${e(t.fullName)}"><h2>${e(t.fullName)}</h2><p>${e(t.venue)} · ${e(t.city)}</p><p>${e(t.bio)}</p>${r?`<span class="badge">${r.status==='accepted'?'Ваш тренер':'Заявка отправлена'}</span>${r.status==='accepted'?`<button onclick="chat(${t.telegramId})">Написать тренеру</button>`:''}`:`<button class="primary" onclick="requestTrainer(${t.telegramId})">Отправить заявку</button>`}</div>`}).join('')||'<p>Тренеров в вашем городе пока нет.</p>'}</div>`}
function requestTrainer(id){formDialog('Заявка тренеру','<p>Отправляйте заявку после договорённости с тренером и оплаты.</p><label>Комментарий: группа, дни, время<textarea name="comment" maxlength="500"></textarea></label>','request',{coach:id})}
function profileView(){const u=state.user;setTimeout(()=>{const f=$('#profile');if(f&&u.role==='coach')loadProfileVenues(f,false);if(f)f.onsubmit=async ev=>{ev.preventDefault();try{state.user=await api('/api/me',Object.fromEntries(new FormData(f)));render();toast('Профиль сохранён')}catch(err){toast(err.message)}}},0);return heading('Профиль',u.role==='coach'?'<button onclick="navigate(\'reports\')">Оплаты и выручка</button>':'')+`<form id="profile" class="card fields">${field('ФИО','fullName',u.fullName)}<label>Город<select name="cityId" onchange="loadProfileVenues(this.form,true)">${state.cities.map(c=>`<option value="${c.id}" ${c.id===u.cityId?'selected':''}>${c.code} · ${c.name}</option>`).join('')}</select></label>${u.role==='coach'?`<label>Клуб / корт<select name="venueId" onchange="selectProfileVenue(this.form)"><option value="">Загрузка справочника…</option></select></label><label>Название площадки<input name="venue" value="${e(u.venue||u.customVenue||'')}"></label><label>Адрес<input name="address" value="${e(u.address||'')}"></label>`:''}<label>О себе<textarea name="bio" maxlength="1000" placeholder="Что вы тренируете, стоимость индивидуальных и групповых занятий">${e(u.bio)}</textarea></label><button class="primary">Сохранить</button></form>`}
function reportPeriod(kind){reportTo=new Date(Date.now()+5*3600000).toISOString().slice(0,10);reportFrom=kind==='year'?reportTo.slice(0,4)+'-01-01':reportTo.slice(0,7)+'-01';render()}
function reportsView(){const valid=reportFrom<=reportTo,list=valid?state.payments.filter(p=>p.date>=reportFrom&&p.date<=reportTo).sort((a,b)=>b.created-a.created):[];return heading('Оплаты и выручка')+`<section class="card revenue-summary"><span>Получено за период</span><h2>${money(list.reduce((n,p)=>n+p.amount,0))}</h2><span>${list.length} оплат · ${list.reduce((n,p)=>n+p.hours,0)} ч начислено</span></section><div class="card report-filters"><div class="tabs"><button onclick="reportPeriod('month')">Этот месяц</button><button onclick="reportPeriod('year')">Этот год</button></div><div class="date-range"><label>С<input type="date" value="${reportFrom}" onchange="reportFrom=this.value;render()"></label><label>По<input type="date" value="${reportTo}" onchange="reportTo=this.value;render()"></label></div>${valid?'':'<p role="alert">Проверьте порядок дат.</p>'}</div><h2>История оплат</h2><div class="payment-list">${list.map(p=>`<article class="card payment-card"><div class="row"><strong>${e(p.name)}</strong><strong class="payment-sum">${money(p.amount)}</strong></div><div class="payment-tags"><span class="badge">+${p.hours} ч</span><span class="meta">${new Date(p.date+'T12:00').toLocaleDateString('ru-RU')}</span></div><div class="meta">${paymentGroupLabel(p)}</div><div class="payment-detail">Оплатил: ${e(p.payer)}${p.comment?`<p>${e(p.comment)}</p>`:''}</div></article>`).join('')||'<div class="card empty">За выбранный период оплат нет.</div>'}</div>`}
function exportGate(){modal('<h2>Выгрузка доступна в Premium</h2><p>Отчёты по заявкам, группам и оплатам.</p><div class="actions"><button class="primary" onclick="closeDialog();navigate(\'premium\')">Подробнее</button><button onclick="closeDialog()">Закрыть</button></div>')}
function premiumView(){return `<section class="premium-hero"><span>TOPCOACH PREMIUM</span><h1>Тренируйте больше.<br>Рутину оставьте нам.</h1><p>Базовый план — для ежедневной работы. Premium — для анализа и роста вашей практики.</p></section><div class="plans"><section class="card plan"><span class="badge">ВАШ ПЛАН</span><h2>Базовый</h2><div class="plan-price">Бесплатно</div><ul><li>👥 Заявки и список учеников</li><li>🎾 Групповые и индивидуальные занятия</li><li>🗓 Календарь и посещаемость</li><li>⏱ Баланс и автоматическое списание часов</li><li>💳 Учёт оплат и выручка за период</li><li>🔔 Уведомления о занятиях, оплатах и отменах</li></ul><p class="meta">Всё для организации тренировок каждый день.</p></section><section class="card plan premium-plan"><span class="badge">СКОРО</span><h2>Premium</h2><div class="plan-price">Больше контроля</div><ul><li>✅ Всё из базового плана</li><li>📥 Выгрузка заявок, групп и оплат</li><li>📊 Подробная аналитика по группам и типам занятий</li><li>📈 Сравнение периодов и динамика выручки</li><li>🗂 Отчёты для работы вне приложения</li></ul><p class="meta">Планируемые преимущества. Цена и лимиты будут объявлены перед запуском.</p><button disabled>Подписка готовится к запуску</button></section></div>`}
let profileVenueRows=[];
async function loadProfileVenues(form,clear){if(!form.elements.venueId)return;const cityId=form.elements.cityId.value;if(clear){form.elements.venue.value='';form.elements.address.value='';}const select=form.elements.venueId;select.disabled=true;select.innerHTML='<option value="">Загрузка…</option>';form.querySelector('button[type=submit],button.primary').disabled=true;try{const rows=await api('/api/venues?cityId='+encodeURIComponent(cityId));if(!form.isConnected||form.elements.cityId.value!==cityId)return;profileVenueRows=rows;const match=clear?null:rows.find(v=>v.name===form.elements.venue.value&&v.address===form.elements.address.value);select.innerHTML='<option value="">Указать вручную</option>'+rows.map(v=>`<option value="${v.id}" ${match?.id===v.id?'selected':''}>${e(v.name)} · ${e(v.address)}</option>`).join('');}catch(error){select.innerHTML='<option value="">Указать вручную</option>';toast('Не удалось загрузить корты. Можно указать вручную.')}finally{if(form.isConnected&&form.elements.cityId.value===cityId){select.disabled=false;form.querySelector('button[type=submit],button.primary').disabled=false}}}
function selectProfileVenue(form){const v=profileVenueRows.find(v=>v.id===form.elements.venueId.value);form.elements.venue.value=v?.name||'';form.elements.address.value=v?.address||''}
function setupMobile(){if(!tg)return;try{if(tg.isVersionAtLeast?.('6.2'))tg.enableClosingConfirmation();if(tg.isVersionAtLeast?.('7.7'))tg.disableVerticalSwipes();if(tg.isVersionAtLeast?.('8.0'))tg.requestFullscreen()}catch{}const safe=()=>{const top=(tg.safeAreaInset?.top||0)+(tg.contentSafeAreaInset?.top||0);document.documentElement.style.setProperty('--tg-top',top+'px');document.documentElement.style.setProperty('--tg-bottom',(tg.safeAreaInset?.bottom||0)+'px')};safe();tg.onEvent?.('safeAreaChanged',safe);tg.onEvent?.('contentSafeAreaChanged',safe)}
$('#theme').onclick=()=>document.body.classList.toggle('dark');async function refresh(){try{state=await api('/api/state');render()}catch(err){if(!state)$('#screen').textContent=err.message;else toast(err.message)}}refresh();setInterval(()=>{if(state&&!$('#dialog').open&&page==='home')refresh()},15000);

function weekCalendar(){const selected=new Date(day+'T12:00:00Z');const monday=new Date(selected);monday.setUTCDate(selected.getUTCDate()-(selected.getUTCDay()+6)%7);return `<div class="week">${Array.from({length:7},(_,i)=>{const d=new Date(monday);d.setUTCDate(d.getUTCDate()+i);const value=d.toISOString().slice(0,10);return `<button class="${value===day?'selected':''}" onclick="day='${value}';render()"><small>${d.toLocaleDateString('ru-RU',{weekday:'short',timeZone:'UTC'})}</small><b>${d.getUTCDate()}</b></button>`}).join('')}</div>`}
function renameStudent(pid){const p=state.students.find(p=>p.telegramId===pid);formDialog('Имя ученика',field('ФИО','name',p.displayName||p.fullName)+'<p>Это имя в вашем списке. Telegram-профиль ученика не изменится.</p>','student_name',{player:pid})}
async function updateAttendance(id,pid,input){const present=input.checked;input.disabled=true;try{state=await api('/api/action',{action:'attendance',id,player:pid,present});input.closest('label').querySelector('.presence-label').textContent=present?'Присутствует':'Отсутствует';render()}catch(error){input.checked=!present;toast(error.message)}finally{input.disabled=false}}

function paymentGroupLabel(payment){const group=state.groups.find(g=>g.members.includes(payment.player));return group?e(group.name)+' · '+e(group.type):'Ученик пока без группы'}
